SELECT CASE WHEN d.budget >= 4368000 THEN 'high' WHEN d.budget >= 1972000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND((100 * SUM(CASE WHEN e.job_title = 'Designer' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_designer, AVG(e.salary) AS avg_salary FROM employees e RIGHT JOIN departments d ON e.dept_id = d.id GROUP BY CASE WHEN d.budget >= 4368000 THEN 'high' WHEN d.budget >= 1972000 THEN 'mid' ELSE 'low' END ORDER BY pct_designer, budget_bucket
